package com.familyfinance.loan; import com.familyfinance.shared.Money; import java.time.LocalDate;
public record LoanInstallmentResponse(long id,int installmentNo,LocalDate dueOn,String principal,String interest,LoanInstallmentStatus status,Long confirmedTransactionId) { static LoanInstallmentResponse from(LoanInstallment i){return new LoanInstallmentResponse(i.getId(),i.getInstallmentNo(),i.getDueOn(),Money.formatCents(i.getPrincipalCents()),Money.formatCents(i.getInterestCents()),i.getStatus(),i.getConfirmedTransaction()==null?null:i.getConfirmedTransaction().getId());} }
